static Permissions createPermissions(Environment environment) throws IOException {
        Permissions policy = new Permissions();
        // read-only dirs
        addPath(policy, environment.binFile(), "read,readlink");
        addPath(policy, environment.libFile(), "read,readlink");
        addPath(policy, environment.pluginsFile(), "read,readlink");
        addPath(policy, environment.configFile(), "read,readlink");
        // read-write dirs
        addPath(policy, environment.tmpFile(), "read,readlink,write,delete");
        addPath(policy, environment.logsFile(), "read,readlink,write,delete");
        for (Path path : environment.dataFiles()) {
            addPath(policy, path, "read,readlink,write,delete");
        }
        for (Path path : environment.dataWithClusterFiles()) {
            addPath(policy, path, "read,readlink,write,delete");
        }
        for (Path path : environment.repoFiles()) {
            addPath(policy, path, "read,readlink,write,delete");
        }
        if (environment.pidFile() != null) {
            addPath(policy, environment.pidFile().getParent(), "read,readlink,write,delete");
        }
        return policy;
    }

public synchronized void verifyIndexMetadata(IndexMetaData metaData, IndexMetaData metaDataUpdate) throws IOException {
        final List<Closeable> closeables = new ArrayList<>();
        try {
            IndicesFieldDataCache indicesFieldDataCache = new IndicesFieldDataCache(settings, new IndexFieldDataCache.Listener() {});
            closeables.add(indicesFieldDataCache);
            IndicesQueryCache indicesQueryCache = new IndicesQueryCache(settings);
            closeables.add(indicesQueryCache);
            // this will also fail if some plugin fails etc. which is nice since we can verify that early
            final IndexService service =
                createIndexService("metadata verification", metaData, indicesQueryCache, indicesFieldDataCache, emptyList());
            closeables.add(() -> service.close("metadata verification", false));
            service.mapperService().merge(metaData, MapperService.MergeReason.MAPPING_RECOVERY, true);
            if (metaData.equals(metaDataUpdate) == false) {
                service.updateMetaData(metaDataUpdate);
            }
        } finally {
            IOUtils.close(closeables);
        }
    }

private void findJavadocs(String commentText) {

    	Collection<JavadocElement> kids = new ArrayList<JavadocElement>();

    	Map<String, Integer> tags = CommentUtil.javadocTagsIn(commentText);
    	for (Map.Entry<String, Integer> entry : tags.entrySet()) {
    		JavadocTag tag = JavadocTag.tagFor(entry.getKey());
    		if (tag == null) continue;
    		kids.add(
    			new JavadocElement(
    				getBeginLine(), getBeginLine(),	// TODO valid?
    				entry.getValue() + 1, entry.getValue() + tag.label.length() + 1 ,tag
    				)
    			);
    	}

    	children = kids.toArray(new Node[kids.size()]);
    }

